    },
    {
      "id": "R2",
      "summary_ko": "상추가 볼에 떨어지는 방식이 비현실적이며 당근이 갑자기 나타남."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "위에서 채소가 던져지는 동안 볼 안에서 채소가 갑자기 나타나고 복제됨."
    },
    {
      "id": "C2",
      "summary_ko": "위로 떠오른 양배추가 동적으로 변형되고 부자연스럽게 공중에 맴돌다가 떨어짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 샐러드로 변하지 않고 볼에 던져지기만 한다는 내용이며, C1은 볼 내부에서 채소가 갑자기 나타나고 복제된다는 내용이므로 결함의 성격이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 샐러드 완성 여부/던져짐에 관한 내용인 반면 C2는 양배추가 공중에서 비정상적으로 머물고 변형되는 현상에 관한 것입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "R2의 당근 등의 갑작스러운 출현 및 비현실적인 낙하 묘사와 C1의 볼 내부에서 채소가 갑자기 나타나고 복제된다는 현상은 동일한 비정상적 출현 현상을 설명합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "R2는 상추의 비현실적인 낙하와 당근 출현을 다루고 C2는 양배추의 공중 부유 및 변형을 다루어 관련되어 보이나 대상과 구체적 물리 오류 묘사에서 차이가 있어 동일성 판단이 불확실합니다."
    }
  ]
}
